body.script:
  // ---------- Particles ----------
  const particlesEl = document.getElementById('particles');
  const particleCount = 40;
  for(let i=0;i<particleCount;i++){
    const p = document.createElement('div');
    p.className = 'p';
    const size = 1 + Math.random()*3;
    p.style.width = size+'px';
    p.style.height = size+'px';
    p.style.left = Math.random()*100+'%';
    p.style.bottom = (Math.random()*10)+'%';
    p.style.animationDuration = (6+Math.random()*8)+'s';
    p.style.animationDelay = (Math.random()*8)+'s';
    particlesEl.appendChild(p);
  }

  // ---------- Keyboard key lighting (random flowing keys) ----------
  const kb = document.getElementById('keyboard');
  const totalKeys = 16*4;
  for(let i=0;i<totalKeys;i++){
    const k = document.createElement('div');
    k.className = 'kb-key';
    k.style.animationDelay = (Math.random()*2.6)+'s';
    if(Math.random() < 0.85) k.classList.add('lit');
    kb.appendChild(k);
  }

  // ---------- Editor typing simulation ----------
  const codeLines = [
`// Codeforces Div.1 F — segment tree optimization`,
`#include <bits/stdc++.h>`,
`using namespace std;`,
``,
`struct SegTree {`,
`    vector<long long> tree, lazy;`,
`    int n;`,
``,
`    void build(int node, int l, int r) {`,
`        if (l == r) { tree[node] = a[l]; return; }`,
`        int mid = (l + r) >> 1;`,
`        build(node*2, l, mid);`,
`        build(node*2+1, mid+1, r);`,
`        tree[node] = tree[node*2] + tree[node*2+1];`,
`    }`,
``,
`    void update(int node, int l, int r, int ql, int qr, long long val) {`,
`        if (qr < l || r < ql) return;`,
`        if (ql <= l && r <= qr) { tree[node] += val; return; }`,
`        propagate(node, l, r);`,
`        int mid = (l + r) >> 1;`,
`        update(node*2, l, mid, ql, qr, val);`,
`        update(node*2+1, mid+1, r, ql, qr, val);`,
`    }`,
`};`,
``,
`int main() {`,
`    ios::sync_with_stdio(false);`,
`    cin.tie(nullptr);`,
`    int n, q; cin >> n >> q;`,
`    SegTree st(n);`,
`    while (q--) { // process queries`,
`        st.update(1, 0, n-1, l, r, val);`,
`    }`,
`    return 0;`,
`}`
  ];

  const editorEl = document.getElementById('editorText');
  let lineIdx = 0, charIdx = 0, renderedHTML = "";

  function typeEditor(){
    if(lineIdx >= codeLines.length){
      setTimeout(()=>{ renderedHTML=""; lineIdx=0; charIdx=0; editorEl.innerHTML=""; typeEditor(); }, 1800);
      return;
    }
    const fullLine = codeLines[lineIdx];
    // strip tags length-aware typing: reveal by rendering full line progressively using a temp div text length
    const plain = fullLine.replace(/<[^>]*>/g,'');
    if(charIdx <= plain.length){
      // Build partial: naive approach — reveal whole line quickly after certain chars for perf, but simulate char by char using textContent overlay
      let partial = "";
      let count = 0;
      let inTag = false;
      for(let ch of fullLine){
        if(ch === '<') inTag = true;
        if(!inTag) count++;
        partial += ch;
        if(ch === '>') inTag = false;
        if(!inTag && count >= charIdx) break;
      }
      editorEl.innerHTML = renderedHTML + partial + '';
      charIdx++;
      setTimeout(typeEditor, 14 + Math.random()*22);
    } else {
      renderedHTML += fullLine + "\n";
      lineIdx++;
      charIdx = 0;
      // auto-scroll effect: keep last ~16 lines
      const linesArr = renderedHTML.split("\n");
      if(linesArr.length > 15){
        renderedHTML = linesArr.slice(linesArr.length-15).join("\n");
      }
      setTimeout(typeEditor, 40);
    }
  }
  typeEditor();

  // ---------- Terminal simulation ----------
  const terminalEl = document.getElementById('terminalText');
  const termSequence = [
    {t:'$ g++ solution.cpp -O2 -o sol', d:900},
    {t:'Compiling...', d:1100},
    {t:'Compiling... done', d:700},
    {t:'$ ./run_tests.sh', d:900},
    {t:'Running Tests...', d:1200},
    {t:'Test 1: Accepted ✓  (12ms)', d:500},
    {t:'Test 2: Accepted ✓  (18ms)', d:500},
    {t:'Test 3: Accepted ✓  (9ms)', d:500},
    {t:'Test 4: Accepted ✓  (21ms)', d:700},
    {t:'All tests passed — Accepted ✓', d:2200},
  ];

  async function runTerminal(){
    terminalEl.innerHTML = "";
    let buffer = [];
    for(const step of termSequence){
      buffer.push(step.t);
      if(buffer.length > 9) buffer.shift();
      terminalEl.innerHTML = buffer.join("
") + '';
      await new Promise(r=>setTimeout(r, step.d));
    }
    await new Promise(r=>setTimeout(r, 900));
    runTerminal();
  }
  runTerminal();

  // ---------- Rating counter subtle flicker ----------
  const ratingEl = document.getElementById('ratingNum');
  const baseRating = 2634;
  setInterval(()=>{
    const delta = Math.floor(Math.random()*5)-2;
    ratingEl.textContent = baseRating + delta;
  }, 2600);
